GUIDE.dbBentRow = GUIDE.dbRow;
const li = a => a.map(x => `<li>${x}</li>`).join('');
// Returns the HTML for the instructions panel. `esc` is passed in to keep this module DOM-free.
export function guideHtml(ex, esc, { first = true } = {}) {
  const g = GUIDE[ex.id];
  if (!g) return `<ul class="cues">${ex.cues.map(c => `<li>${esc(c)}</li>`).join('')}</ul>`;
  const sec = (t, body, o = false) => `<details class="gd" ${o ? 'open' : ''}><summary>${t}</summary>${body}</details>`;
  return `${first ? `<p class="gd-intro">${esc(g.intro)}</p>` : ''}
    ${sec('How to do it', `<ol class="steps">${li(g.steps.map(esc))}</ol>`, true)}
    ${sec('Breathing', `<p>${esc(g.breathe)}</p>`, first)}
    ${sec('You should feel it in', `<p>${esc(g.feel)}</p>`, first)}
    ${sec('Common mistakes', `<ul class="mist">${li(g.mistakes.map(esc))}</ul>`, first)}
    ${sec('Too hard? Make it easier', `<p>${esc(g.easier)}</p>${g.stop ? `<p class="stop">${esc(g.stop)}</p>` : ''}`, first)}`;
}

// Short on-screen cues are derived from the detailed steps, so the two can never disagree.
export function shortCues(ex, n = 3) {
  const g = GUIDE[ex.id];
  if (!g) return ex.cues;
  const clip = s => { let t = s.split(/(?<=[.!?])\s/)[0].split(' — ')[0].replace(/\.$/, ''); if (t.length > 70) { const m = t.match(/^(.{25,70}?)(,| until | so | as if )/); if (m) t = m[1]; } return t; };
  return g.steps.slice(0, n).map(clip);
}
export const videoUrl = ex => `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name + ' proper form for beginners')}`;

